import math

def fibonacci(index):
    if index <= 0:
        return 0
    elif index == 1:
        return 1
    else:
        phi = (1 + math.sqrt(5)) / 2
        psi = (1 - math.sqrt(5)) / 2
        return int((1 / math.sqrt(5)) * (phi ** index - psi ** index))
```

